"""Small numeric helpers."""


def mean(values):
    """Return the arithmetic mean of a non-empty sequence of numbers."""
    values = list(values)
    if not values:
        raise ValueError('mean requires at least one value')
    return sum(values) / len(values)

files.pkg/paging.py:
"""Pagination helpers."""


def page_count(total, per_page):
    """Return how many pages are needed to show total items, per_page per page."""
    if isinstance(total, bool) or not isinstance(total, int) or total < 0:
        raise ValueError('total must be a non-negative integer')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page < 1:
        raise ValueError('per_page must be a positive integer')
    return total // per_page


def page_slice(items, page, per_page):
    """Return the items shown on 1-based page as a list."""
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be a positive integer')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page < 1:
        raise ValueError('per_page must be a positive integer')
    start = (page - 1) * per_page
    return list(items[start:start + per_page])

