"""Row formatting for the account report."""


def format_user(name, age):
    if not isinstance(name, str) or not name.strip():
        raise ValueError('name must be a non-empty string')
    if isinstance(age, bool) or not isinstance(age, int) or age < 0:
        raise ValueError('age must be a non-negative integer')
    return f'user: {name.strip()} ({age})'


def format_admin(name, age):
    if not isinstance(name, str) or not name.strip():
        raise ValueError('name must be a non-empty string')
    if isinstance(age, bool) or not isinstance(age, int) or age < 0:
        raise ValueError('age must be a non-negative integer')
    return f'admin: {name.strip()} ({age})'

files.pkg/ratio.py:
"""Ratio helpers."""


def bucket(numerator, denominator):
    """Return numerator divided by denominator using floor division.

    The result must equal Python's numerator // denominator for every pair of
    integers with a nonzero denominator.
    """
    if denominator == 0:
        raise ZeroDivisionError('denominator must be nonzero')
    return int(numerator / denominator)

